STYLE='''<style>.detail-seo{max-width:960px;margin:28px auto;padding:0 16px}.detail-seo-box{background:#fff;color:#334155;border:1px solid #e2e8f0;border-radius:18px;padding:24px;box-shadow:0 8px 30px rgba(15,23,42,.05)}.detail-seo h2{font-size:21px;color:#0f172a;margin:0 0 12px}.detail-seo h3{font-size:16px;color:#0f172a;margin:22px 0 8px}.detail-seo p{line-height:1.8;margin:8px 0}.detail-seo-links{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.detail-seo-links a{padding:8px 11px;border-radius:10px;background:#eff6ff;color:#1d4ed8;text-decoration:none;font-weight:700;font-size:13px}</style>'''

def block(title,p1,p2):
    return STYLE+f'''<section class="detail-seo" data-static-seo="1"><div class="detail-seo-box"><h2>{title}</h2><p>{p1}</p><p>{p2}</p><h3>함께 이용하기 좋은 서비스</h3><div class="detail-seo-links"><a href="/calculator/">계산기 전체보기</a><a href="/stock/">국내 증시 보기</a><a href="/apt/">아파트 실거래가</a><a href="/lotto/">로또 정보</a></div></div></section>'''

def inject(path, html):
    html=re.sub(r'<style>\.detail-seo\{.*?</section>','',html,flags=re.S)
    marker='<footer'
    pos=html.lower().rfind(marker)
    if pos<0: pos=html.lower().rfind('</body>')
    if pos<0: return html
    return html[:pos]+block(*html_data[path])+"\n"+html[pos:]

html_data={}
for name,data in CALC.items(): html_data[Path('calculator')/name]=data
for slug,data in GAME.items(): html_data[Path('games')/slug/'index.html']=data

for path,data in html_data.items():
    if not path.exists():
        print('SKIP missing',path); continue
    text=path.read_text(encoding='utf-8')
    # remove prior generated block safely
    text=re.sub(r'<style>\.detail-seo\{.*?<section class="detail-seo" data-static-seo="1">.*?</section>\n?','',text,flags=re.S)
    pos=text.find('<!-- CRAWL_LINKS_START -->')
    if pos<0: pos=text.lower().rfind('<footer')
    if pos<0: pos=text.lower().rfind('</body>')
    if pos<0: print('SKIP no insertion point',path); continue
    text=text[:pos]+block(*data)+'\n'+text[pos:]
    if path.read_text(encoding='utf-8') != text:
        path.write_text(text,encoding='utf-8')
    print('ENHANCED',path)
